const groveTree = Object.fromEntries(GROVES.map((g) => [g.id, g.tree])) as Record<GroveId, TreeVariant>;

function build(): Concept[] {
  const list: Concept[] = RAW.map(([id, name, grove, level, pre, lore, formula, apps, aliases]) => ({
    id, name, grove, level, depth: 0,
    description: lore,
    intuition: "",
    formula,
    prerequisites: pre,
    unlocks: [],
    applications: apps,
    treeVariant: groveTree[grove],
    aliases: aliases ?? [],
  }));
  const byId = new Map(list.map((c) => [c.id, c]));
  for (const c of list) for (const p of c.prerequisites) {
    const parent = byId.get(p);
    if (!parent) throw new Error(`Unknown prerequisite ${p} for ${c.id}`);
    parent.unlocks.push(c.id);
  }
  const memo = new Map<string, number>();
  const depthOf = (id: string, stack = new Set<string>()): number => {
    if (memo.has(id)) return memo.get(id)!;
    if (stack.has(id)) throw new Error(`Cycle at ${id}`);
    stack.add(id);
    const c = byId.get(id)!;
    const d = c.prerequisites.length ? 1 + Math.max(...c.prerequisites.map((p) => depthOf(p, stack))) : 0;
    stack.delete(id);
    memo.set(id, d);
    return d;
  };
  for (const c of list) {
    c.depth = depthOf(c.id);
    const next = c.unlocks.map((u) => byId.get(u)!.name);
    c.intuition = next.length
      ? `Once this idea takes root, it opens the way to ${next.slice(0, 4).join(", ")}${next.length > 4 ? " and more" : ""}.`
      : "This is a canopy tip — a place where this branch of the forest flowers into practice.";
  }
  return list;
}

export const CONCEPTS: Concept[] = build();
export const CONCEPT_BY_ID: Map<string, Concept> = new Map(CONCEPTS.map((c) => [c.id, c]));
export const GROVE_BY_ID: Map<GroveId, Grove> = new Map(GROVES.map((g) => [g.id, g]));
